/* Mandatory reset rule */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #1f1b24;
  --card-bg: #2b233a;
  --wood-dark: #3a2215;
  --wood-mid: #5c371d;
  --wood-light: #8e582d;
  --accent-gold: #f4b41a;
  --text-main: #f5eedc;
  --text-dim: #bda893;
  --spine-1: #d95763;
  --spine-2: #37946e;
  --spine-3: #5b6ee1;
  --spine-4: #ac3232;
  --spine-5: #639bff;
  --spine-6: #df7126;
  --spine-7: #696a6a;
  --spine-8: #8f563b;
  --focus-ring: #ffea75;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: "Courier New", Courier, monospace, monospace;
  font-size: 16px;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 12px;
}

.shelf-app {
  width: 100%;
  max-width: 860px;
  background-color: var(--card-bg);
  border: 4px solid var(--wood-light);
  box-shadow:
    0 0 0 4px var(--wood-dark),
    12px 12px 0 0 #0f0c14;
  padding: 28px 24px;
  border-radius: 2px;
}

.shelf-header {
  text-align: center;
  margin-bottom: 24px;
}

.shelf-title {
  font-size: 28px;
  color: var(--accent-gold);
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 var(--wood-dark);
  margin-bottom: 6px;
}

.shelf-subtitle {
  font-size: 16px;
  color: var(--text-dim);
}

.shelf-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: flex-end;
  justify-content: space-between;
  background: #20182c;
  padding: 16px;
  border: 3px solid var(--wood-mid);
  margin-bottom: 28px;
}

.control-group {
  display: flex;
  flex-direction: column;
  flex: 1 1 200px;
  gap: 6px;
}

.control-group-button {
  flex: 0 1 200px;
}

.control-label {
  font-size: 14px;
  font-weight: bold;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.pixel-input,
.pixel-select,
.pixel-btn {
  font-family: inherit;
  font-size: 16px;
  color: var(--text-main);
  background-color: #171121;
  border: 3px solid var(--wood-light);
  padding: 10px 12px;
  border-radius: 0;
  outline: none;
  transition: border-color 0.15s ease, transform 0.05s ease;
}

.pixel-input:focus,
.pixel-select:focus,
.pixel-btn:focus {
  border-color: var(--focus-ring);
  outline: 2px solid var(--focus-ring);
  outline-offset: 1px;
}

.pixel-btn {
  cursor: pointer;
  background-color: var(--wood-mid);
  font-weight: bold;
  text-align: center;
  width: 100%;
  box-shadow: 0 4px 0 0 var(--wood-dark);
}

.pixel-btn:hover {
  background-color: #6e4222;
}

.pixel-btn:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 0 var(--wood-dark);
}

.bookcase {
  background: #171220;
  border: 4px solid var(--wood-dark);
  padding: 20px 16px 0 16px;
  position: relative;
}

.shelf-plank {
  background-color: var(--wood-mid);
  height: 16px;
  border-top: 4px solid var(--wood-light);
  border-bottom: 4px solid var(--wood-dark);
  box-shadow: inset 0 2px 0 0 rgba(255, 255, 255, 0.15);
}

.shelf-plank.top-edge {
  margin-bottom: 20px;
  height: 12px;
}

.shelf-beam {
  margin-top: 0;
}

.books-display {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: center;
  gap: 14px;
  min-height: 250px;
  padding-bottom: 2px;
}

.book-item {
  position: relative;
  width: 76px;
  height: var(--book-height, 220px);
  background-color: var(--book-color, var(--spine-1));
  border: 3px solid #140d1a;
  box-shadow:
    inset 4px 0 0 0 rgba(255, 255, 255, 0.25),
    inset -4px 0 0 0 rgba(0, 0, 0, 0.4),
    4px 0 0 0 rgba(0, 0, 0, 0.5);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 8px 4px;
  transition: transform 0.15s ease, filter 0.15s ease;
  outline: none;
}

.book-item:hover,
.book-item:focus {
  transform: translateY(-8px);
  filter: brightness(1.15);
  border-color: var(--focus-ring);
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.book-spine-dec-top,
.book-spine-dec-bottom {
  height: 6px;
  width: 100%;
  background-color: var(--accent-gold);
  opacity: 0.85;
  border-top: 1px solid #140d1a;
  border-bottom: 1px solid #140d1a;
}

.book-spine-content {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-size: 13px;
  font-weight: bold;
  letter-spacing: 1px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-height: 140px;
  color: #fff;
  text-shadow: 1px 1px 0 #000;
  text-align: center;
  margin: auto auto;
}

.book-year-tag {
  font-size: 11px;
  text-align: center;
  color: var(--accent-gold);
  background: rgba(0, 0, 0, 0.55);
  padding: 2px 0;
  font-weight: bold;
  border-radius: 1px;
}

.pixel-empty-state {
  text-align: center;
  padding: 40px 16px;
  color: var(--text-dim);
  font-size: 18px;
  font-style: italic;
}

.shelf-status {
  margin-top: 18px;
  display: flex;
  justify-content: flex-end;
  font-size: 14px;
  color: var(--text-dim);
}

@media (max-width: 520px) {
  .shelf-app {
    padding: 16px 12px;
  }

  .shelf-controls {
    flex-direction: column;
    align-items: stretch;
  }

  .control-group-button {
    flex: 1 1 auto;
  }

  .book-item {
    width: 62px;
  }

  .book-spine-content {
    font-size: 12px;
  }
}

const BOOKS = [
  { id: 1, title: "Dune", author: "Frank Herbert", year: 1965, height: 230, color: "#d95763" },
  { id: 2, title: "Neuromancer", author: "William Gibson", year: 1984, height: 200, color: "#37946e" },
  { id: 3, title: "The Hobbit", author: "J.R.R. Tolkien", year: 1937, height: 210, color: "#5b6ee1" },
  { id: 4, title: "Fahrenheit 451", author: "Ray Bradbury", year: 1953, height: 190, color: "#ac3232" },
  { id: 5, title: "Snow Crash", author: "Neal Stephenson", year: 1992, height: 240, color: "#639bff" },
  { id: 6, title: "Foundation", author: "Isaac Asimov", year: 1951, height: 215, color: "#df7126" },
  { id: 7, title: "1984", author: "George Orwell", year: 1949, height: 195, color: "#696a6a" },
  { id: 8, title: "Solaris", author: "Stanislaw Lem", year: 1961, height: 205, color: "#8f563b" }
];

const state = {
  searchQuery: "",
  sortField: "title",
  isAscending: true
};

const booksGrid = document.getElementById("books-grid");
const emptyMessage = document.getElementById("empty-message");
const searchInput = document.getElementById("search-input");
const sortSelect = document.getElementById("sort-field");
const orderToggleBtn = document.getElementById("order-toggle");
const orderLabel = document.getElementById("order-label");
const bookCountText = document.getElementById("book-count-text");

function getFilteredAndSortedBooks() {
  const query = state.searchQuery.trim().toLowerCase();

  const filtered = BOOKS.filter((book) => {
    if (!query) return true;
    return (
      book.title.toLowerCase().includes(query) ||
      book.author.toLowerCase().includes(query)
    );
  });

  filtered.sort((a, b) => {
    const field = state.sortField;
    let valA = a[field];
    let valB = b[field];

    if (typeof valA === "string") {
      valA = valA.toLowerCase();
      valB = valB.toLowerCase();
    }

    if (valA < valB) return state.isAscending ? -1 : 1;
    if (valA > valB) return state.isAscending ? 1 : -1;
    return 0;
  });

  return filtered;
}

function renderBooks() {
  const books = getFilteredAndSortedBooks();
  booksGrid.innerHTML = "";

  if (books.length === 0) {
    emptyMessage.hidden = false;
  } else {
    emptyMessage.hidden = true;
    books.forEach((book) => {
      const bookEl = document.createElement("article");
      bookEl.className = "book-item";
      bookEl.tabIndex = 0;
      bookEl.setAttribute("role", "listitem");
      bookEl.setAttribute(
        "aria-label",
        `${book.title} by ${book.author}, published in ${book.year}`
      );
      bookEl.style.setProperty("--book-height", `${book.height}px`);
      bookEl.style.setProperty("--book-color", book.color);

      bookEl.innerHTML = `
        <div class="book-spine-dec-top"></div>
        <div class="book-spine-content" title="${book.title} - ${book.author}">${book.title}</div>
        <div class="book-year-tag">${book.year}</div>
        <div class="book-spine-dec-bottom"></div>
      `;

      booksGrid.appendChild(bookEl);
    });
  }

  bookCountText.textContent = `Showing ${books.length} of ${BOOKS.length} books`;
}

searchInput.addEventListener("input", (e) => {
  state.searchQuery = e.target.value;
  renderBooks();
});

sortSelect.addEventListener("change", (e) => {
  state.sortField = e.target.value;
  renderBooks();
});

sortSelect.addEventListener("input", (e) => {
  state.sortField = e.target.value;
  renderBooks();
});

orderToggleBtn.addEventListener("click", () => {
  state.isAscending = !state.isAscending;
  const arrow = state.isAscending ? "\u2191" : "\u2193";
  const text = state.isAscending ? "Ascending" : "Descending";
  orderLabel.innerHTML = `${text} (${arrow})`;
  orderToggleBtn.setAttribute("aria-label", `Toggle sort direction: ${text}`);
  renderBooks();
});

document.addEventListener("DOMContentLoaded", () => {
  renderBooks();
});
